**Тип:** простой класс с полем и методом.
<pre class="code-block"><code>class IntNumber {
    int value;
public:
    IntNumber(int v) : value(v) {}
    int remainder() const { return value % 5; }
};

int main() {
    IntNumber num(17);
    cout << num.remainder() << endl; // 2
    return 0;
}</code></pre>

**Тип:** наследование с virtual/override.
**Ключевое:** virtual print() в Base, override в Derived, указатель Base* вызывает метод реального типа.
<pre class="code-block"><code>class Point2D {
protected:
    double x, y;
public:
    Point2D(double x, double y) : x(x), y(y) {}
    virtual void print() {
        cout << "x=" << x << ", y=" << y;
    }
    virtual ~Point2D() {}
};

class Point3D : public Point2D {
    double z;
public:
    Point3D(double x, double y, double z)
        : Point2D(x, y), z(z) {}
    void print() override {
        Point2D::print();
        cout << ", z=" << z;
    }
};

int main() {
    Point2D p2(1, 2);
    Point3D p3(3, 4, 5);
    Point2D* p = &p2;
    p->print(); cout << endl;  // x=1, y=2
    p = &p3;
    p->print(); cout << endl;  // x=3, y=4, z=5
    return 0;
}</code></pre>

**Тип:** свой класс исключения от out_of_range.
<pre class="code-block"><code>class TimeError : public out_of_range {
    int h, m, s;
public:
    TimeError(int h, int m, int s)
        : out_of_range("Invalid time"), h(h), m(m), s(s) {}
    void print() const {
        cerr << what() << ": " << h << ":" << m << ":" << s << endl;
    }
};

class Time {
    int h, m, s;
public:
    Time(int h, int m, int s) : h(h), m(m), s(s) {
        if (h<0||h>23||m<0||m>59||s<0||s>59)
            throw TimeError(h, m, s);
    }
    void print() const {
        cout << h << ":" << m << ":" << s << endl;
    }
};

int main() {
    try {
        Time t1(10, 30, 0); t1.print();
        Time t2(25, 99, -1);
    }
    catch (const TimeError& e) { e.print(); }
    return 0;
}</code></pre>

**Тип:** два потока + lock_guard для синхронизации.
<pre class="code-block"><code>#include <thread>
#include <mutex>
mutex mtx;

void printNumbers(int n, const string& name) {
    for (int i = 1; i <= n; i++) {
        lock_guard<mutex> lock(mtx);
        cout << name << ": " << i << endl;
    }
}

int main() {
    thread t1(printNumbers, 5, "T1");
    thread t2(printNumbers, 5, "T2");
    t1.join(); t2.join();
    return 0;
}</code></pre>

**Тип:** наследование БЕЗ virtual → указатель Base* вызывает Base::print().
<pre class="code-block"><code>class Square {
protected:
    double side;
public:
    Square(double s) : side(s) {}
    double area() { return side * side; }
    void print() {
        cout << "side=" << side << ", area=" << area();
    }
};

class Cube : public Square {
public:
    Cube(double s) : Square(s) {}
    double volume() { return area() * side; }
    void print() {
        cout << "side=" << side << ", V=" << volume();
    }
};

int main() {
    Square sq(5); Cube cu(5);
    Square* p = &sq;
    p->print(); cout << endl;  // side=5, area=25
    p = &cu;
    p->print(); cout << endl;  // side=5, area=25 (статически!)
    cu.print(); cout << endl;  // side=5, V=125
    return 0;
}</code></pre>

**Тип:** оповещение от дочернего потока главному.
<pre class="code-block"><code>#include <thread>
#include <mutex>
#include <condition_variable>
#include <cstdlib>
mutex mtx;
condition_variable cv;
bool done = false;

void printRandom(int n, const string& name) {
    for (int i = 0; i < n; i++) {
        lock_guard<mutex> lk(mtx);
        cout << name << ": " << rand()%100 << endl;
    }
    { lock_guard<mutex> lk(mtx); done = true; }
    cv.notify_one();
}

int main() {
    srand(42);
    thread t(printRandom, 5, "Child");
    unique_lock<mutex> lock(mtx);
    cv.wait(lock, []{ return done; });
    cout << "Main: child done!" << endl;
    t.join();
    return 0;
}</code></pre>
